// Package media is streamlab's synthetic content (docs/streamlab/PLAN.md
// D2): torrent layouts whose bytes are a pure function of (seed, offset), so
// every byte a reader gets can be checked and nothing is stored.
//
// The seeder, the integrity check and later the fake CDN all read from
// Layout.ReadAt: it is the single source of truth.
package media

import (
	"errors"
	"fmt"
	"io"
	"path"
	"strings"
)

// Container is the header a file's bytes start with. The rest of the file
// stays generated.
type Container string

const (
	// Raw is a file of generated bytes only.
	Raw Container = ""
	// MKV starts with an EBML header (DocType matroska) and a Segment.
	MKV Container = "mkv"
	// MP4 is ftyp, then mdat up to a moov box at the end of the file
	// (not fast-start).
	MP4 Container = "mp4"
)

// DefaultMoovSize is an MP4's moov box size when its FileSpec leaves it 0.
const DefaultMoovSize = 256 << 10

// minPieceLength is the BitTorrent chunk size; pieces are a power of two of
// at least one chunk.
const minPieceLength = 16 << 10

// FileSpec is one file of a Spec.
type FileSpec struct {
	// Path is relative to the torrent's folder, "/"-separated. It is empty
	// for a single-file torrent, whose file is named Spec.Name.
	Path      string    `json:"path,omitempty"`
	Size      int64     `json:"size"`
	Container Container `json:"container,omitempty"`
	// MoovSize is an MP4's moov box size, at the end of the file
	// (0: DefaultMoovSize).
	MoovSize int64 `json:"moov_size,omitempty"`
}

// Spec describes a layout. It's plain data: scenarios declare it, and its
// JSON keys the metainfo cache.
type Spec struct {
	// Name is the torrent's name: the file name of a single-file torrent,
	// the folder of a multi-file one.
	Name        string     `json:"name"`
	Seed        uint64     `json:"seed"`
	PieceLength int64      `json:"piece_length"`
	Files       []FileSpec `json:"files"`
}

// SingleFile is the spec of a one-file torrent named name.
func SingleFile(name string, seed uint64, pieceLength, size int64, c Container) Spec {
	return Spec{
		Name:        name,
		Seed:        seed,
		PieceLength: pieceLength,
		Files:       []FileSpec{{Size: size, Container: c}},
	}
}

// EpisodePack is the spec of a season folder: episodes files of one size,
// named like Show.S01E02.mkv, in episode order. A player that finishes one
// episode opens the next file in torrent order.
func EpisodePack(show string, season, episodes int, seed uint64, pieceLength, size int64, c Container) Spec {
	ext := string(c)
	if ext == "" {
		ext = "bin"
	}
	s := Spec{
		Name:        fmt.Sprintf("%s.S%02d", show, season),
		Seed:        seed,
		PieceLength: pieceLength,
	}
	for e := 1; e <= episodes; e++ {
		s.Files = append(s.Files, FileSpec{
			Path:      fmt.Sprintf("%s.S%02dE%02d.%s", show, season, e, ext),
			Size:      size,
			Container: c,
		})
	}
	return s
}

// File is one file of a layout, where it sits in the torrent.
type File struct {
	// Path is the file's path as anacrolix and torrent.TorrentFileHandle
	// name it: Name for a single-file torrent, Name/<path> otherwise.
	Path      string
	Offset    int64 // torrent-absolute
	Size      int64
	Container Container
}

// Layout is a validated Spec: its files in torrent order and the bytes they
// hold. It's immutable and safe for concurrent use.
type Layout struct {
	spec    Spec
	files   []File
	size    int64
	patches []patch // container headers, sorted by offset
}

// New validates spec and returns its layout.
func New(spec Spec) (*Layout, error) {
	if err := spec.validate(); err != nil {
		return nil, err
	}
	l := &Layout{spec: spec}
	l.spec.Files = append([]FileSpec(nil), spec.Files...)
	for _, fs := range l.spec.Files {
		p := spec.Name
		if fs.Path != "" {
			p += "/" + fs.Path
		}
		f := File{Path: p, Offset: l.size, Size: fs.Size, Container: fs.Container}
		l.files = append(l.files, f)
		l.patches = append(l.patches, containerPatches(f, fs.MoovSize)...)
		l.size += fs.Size
	}
	return l, nil
}

// MustNew is New for specs known to be valid; it panics otherwise.
func MustNew(spec Spec) *Layout {
	l, err := New(spec)
	if err != nil {
		panic(err)
	}
	return l
}

func (s Spec) validate() error {
	if s.Name == "" || strings.Contains(s.Name, "/") {
		return fmt.Errorf("media: invalid torrent name %q", s.Name)
	}
	if s.PieceLength < minPieceLength || s.PieceLength&(s.PieceLength-1) != 0 {
		return fmt.Errorf("media: piece length %d isn't a power of two of at least %d", s.PieceLength, minPieceLength)
	}
	if len(s.Files) == 0 {
		return errors.New("media: no files")
	}
	single := len(s.Files) == 1 && s.Files[0].Path == ""
	seen := make(map[string]bool, len(s.Files))
	for _, f := range s.Files {
		if !single && (f.Path == "" || path.Clean(f.Path) != f.Path || strings.HasPrefix(f.Path, "/") || strings.HasPrefix(f.Path, "..")) {
			return fmt.Errorf("media: invalid file path %q (multi-file paths are relative and clean)", f.Path)
		}
		if seen[f.Path] {
			return fmt.Errorf("media: duplicate file path %q", f.Path)
		}
		seen[f.Path] = true
		if f.Size <= 0 {
			return fmt.Errorf("media: file %q has size %d", f.Path, f.Size)
		}
		if err := validateContainer(f); err != nil {
			return fmt.Errorf("media: file %q: %w", f.Path, err)
		}
	}
	return nil
}

// Spec returns the layout's spec.
func (l *Layout) Spec() Spec {
	s := l.spec
	s.Files = append([]FileSpec(nil), l.spec.Files...)
	return s
}

// Name is the torrent's name.
func (l *Layout) Name() string { return l.spec.Name }

// Seed is the content's seed.
func (l *Layout) Seed() uint64 { return l.spec.Seed }

// PieceLength is the torrent's piece length.
func (l *Layout) PieceLength() int64 { return l.spec.PieceLength }

// Size is the torrent's total length.
func (l *Layout) Size() int64 { return l.size }

// NumPieces is how many pieces the torrent has.
func (l *Layout) NumPieces() int {
	return int((l.size + l.spec.PieceLength - 1) / l.spec.PieceLength)
}

// Files returns the files in torrent order.
func (l *Layout) Files() []File { return append([]File(nil), l.files...) }

// FileReader reads file i of the layout, file-relative.
func (l *Layout) FileReader(i int) *io.SectionReader {
	f := l.files[i]
	return io.NewSectionReader(l, f.Offset, f.Size)
}

// ReadAt reads the torrent's bytes at the torrent-absolute offset off. Any
// offset can be read in any order: the bytes depend only on the spec.
func (l *Layout) ReadAt(p []byte, off int64) (int, error) {
	if off < 0 {
		return 0, fmt.Errorf("media: negative offset %d", off)
	}
	if off >= l.size {
		return 0, io.EOF
	}
	n := len(p)
	if rem := l.size - off; int64(n) > rem {
		n = int(rem)
	}
	generate(l.spec.Seed, p[:n], off)
	l.applyPatches(p[:n], off)
	if n < len(p) {
		return n, io.EOF
	}
	return n, nil
}
